const LESSON_MAP = Object.fromEntries(LESSONS.map((l) => [String(l.id), l]));

function getLesson(idOrSlug) {
  if (!idOrSlug) return LESSONS[0];
  return (
    LESSON_MAP[String(idOrSlug)] ||
    LESSONS.find((l) => l.slug === idOrSlug) ||
    LESSONS[0]
  );
}
