        h('span', { class: 'small muted' }, t('คลิกเลือกสถานะสมอง หรือเลื่อนแถบมิกเซอร์ด้านล่างเพื่อผสมคลื่นเอง', 'Click a brain state preset or drag the mixer sliders below to blend your own rhythms'))
