  const dx = m1[0] - m0[0];
  const dy = m1[1] - m0[1];
  let wx = invXX * dx + invXY * dy;
  let wy = invXY * dx + invYY * dy;
  const norm = Math.hypot(wx, wy) || 1;
  wx /= norm;
  wy /= norm;

  const midX = 0.5 * (m0[0] + m1[0]);
  const midY = 0.5 * (m0[1] + m1[1]);
  const b = -(wx * midX + wy * midY);

